-- -----------------------------------------------------------------------------------------
SET IDENTITY_INSERT [dbo].[ClinicalEntries] ON;
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (2, 2, 9, 3, N'Chảy máu nướu răng tự phát khi chải răng, có mùi hôi miệng.', N'Vôi răng dưới nướu nhiều toàn hàm, tụt nướu nhẹ 1-2mm vùng răng cửa hàm dưới, túi nha chu nông 3mm.', N'Viêm nha chu mạn tính độ 2 (K05.3), cao răng dưới nướu độ 3.', N'Nướu phù nề sưng đỏ viền quanh các kẽ răng.', N'Lấy cao răng toàn phần bằng máy siêu âm Woodpecker, đánh bóng toàn hàm bằng bột Proxyt, bơm rửa túi nha chu bằng Povidine 10%.', CAST(N'2026-10-12T10:10:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (3, 6, 13, 6, N'Răng ố vàng xỉn màu do uống trà, cà phê nhiều năm, mong muốn răng trắng sáng tự nhiên.', N'Màu răng ban đầu A3.5 (bảng so màu Vita), men răng chắc khỏe, không có lỗ sâu hoạt động.', N'Nhiễm màu ngoại sinh men răng do sắc tố thực phẩm độ 3.', N'Mô mềm săn chắc, đường cười cân đối.', N'Bảo vệ viền nướu bằng composite lỏng Gingival Barrier, quét thuốc tẩy trắng Opalescence Boost 40%, chiếu đèn Laser Beyond Whitening 3 chu kỳ x 15 phút. Nâng tông lên màu A1.', CAST(N'2026-10-12T09:55:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (4, 7, 16, 9, N'Mẹ đưa bé đi khám phòng ngừa sâu răng khi mới mọc răng hàm vĩnh viễn đầu tiên.', N'Răng số 6 (16, 26, 36, 46) đã nhú hoàn toàn khỏi nướu, rãnh giải phẫu mặt nhai rất sâu và hẹp, đọng mảng bám.', N'Hố rãnh sâu nguy cơ cao sâu răng vĩnh viễn sớm.', N'Răng sữa phát triển tốt, khớp cắn sữa ổn định.', N'Làm sạch rãnh nhai bằng chổi cước và bột đánh bóng không flour, xoi mòn men răng, bôi keo trám bít hố rãnh Sealant Clinpro 3M, chiếu đèn quang trùng hợp 20 giây.', CAST(N'2026-10-12T10:10:00.0000000' AS DateTime2), NULL)
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (5, 1, 83, 6, N'Răng ê buốt nhẹ khi uống nước lạnh', N'Rãnh sâu ngà nông mặt nhai R35', N'Sâu ngà nông răng 35', NULL, N'Chỉ định trám thẩm mỹ Composite', CAST(N'2026-10-14T07:59:16.5995948' AS DateTime2), NULL)
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (6, 13, NULL, 6, N'Đau nhức răng hàm khi nhai đồ cứng', N'Vỡ mẻ múi ngoài răng 46', N'Nứt vỡ thân răng 46', NULL, N'Chỉ định điều trị tủy và bọc sứ bảo tồn', CAST(N'2026-10-14T07:59:36.4565142' AS DateTime2), NULL)
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (7, 14, 85, 6, N'Sâu răng hàm gây dắt thức ăn', N'Lỗ sâu kẽ R16-R17 sâu ngà trung bình', N'Sâu kẽ răng 16, 17', NULL, N'Nạo sạch ngà mủn, hàn trám xoang II Composite', CAST(N'2026-10-14T08:45:36.9867006' AS DateTime2), NULL)
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (9, 6, 95, 3, N'Sưng đau vùng góc hàm trái, há miệng hạn chế, ăn nhai cấn má.', N'Răng 38 mọc lệch 90 độ, lợi trùm viêm đỏ có mủ nhẹ, dắt thức ăn kẽ R37-R38.', N'Răng khôn 38 mọc lệch ngầm kẹt xương (K01.1), viêm lợi trùm cấp.', N'Vệ sinh răng miệng trung bình.', N'Gây tê tại chỗ Lidocain 2%, rạch vạt niêm mạc màng xương, chia cắt thân và chân răng bằng tay khoan siêu âm, nhổ răng trọn vẹn, khâu đóng 2 mũi Vicryl 4.0.', CAST(N'2026-10-15T13:21:43.8127730' AS DateTime2), NULL)
INSERT [dbo].[ClinicalEntries] ([ClinicalEntryId], [MedicalRecordId], [AppointmentId], [DentistUserId], [Symptoms], [ClinicalFindings], [Diagnosis], [DentalConditions], [ClinicalNotes], [CreatedAt], [UpdatedAt]) VALUES (10, 24, NULL, 3, N'Ê buốt răng khi ăn đồ nóng lạnh', N'Mòn cổ răng mặt ngoài R24, R25', N'Mòn ngót cổ răng (K03.1)', NULL, N'Hàn trám bít cổ răng men ngà bằng GIC Fuji IX', CAST(N'2026-10-26T05:59:43.1014817' AS DateTime2), NULL)
